using Microsoft.Extensions.Compliance.Classification;

namespace Community.Zabbix;

/// <summary>
/// Provides the SDK's data taxonomy, for the host's redaction pipeline. A classified
/// <c>[LoggerMessage]</c> parameter never reaches a sink unredacted: the SDK's log methods are generated by the extended
/// generator (<c>Microsoft.Extensions.Telemetry.Abstractions</c>), which keeps a classified value out of the formatted
/// message and the state even when the host never enables redaction (as of 10.9.0 the value is dropped by a plain
/// logger and erased by <c>AddRedaction()</c>'s default fallback). <c>AddZabbixRedaction</c> is the explicit form.
/// </summary>
public static class ZabbixDataClassifications
{
    /// <summary>The taxonomy's name.</summary>
    public const string TaxonomyName = "Zabbix";

    /// <summary>A credential: an API token, a session id, a password, a pre-shared key. Never rendered; erased in every environment.</summary>
    public static DataClassification Secret { get; } = new(TaxonomyName, nameof(Secret));

    /// <summary>Data about a person: a user name. The application chooses its redactor (HMAC, erase); unregistered, the fallback erases it.</summary>
    public static DataClassification Personal { get; } = new(TaxonomyName, nameof(Personal));

    /// <summary>
    /// An item key with its parameters (<c>web.page.get[host,,user:password]</c>, <c>db.odbc.select[…]</c>): a key's
    /// parameters can carry a credential, a connection string or a person's name, so a key is classified wherever it is
    /// logged. A key's name alone (<c>web.page.get</c>) is not. <c>AddZabbixRedaction</c> registers
    /// <see cref="ZabbixItemKeyRedactor"/> for it (the name stays, the parameters are masked); the application can register
    /// another (pass-through on a trusted sink, erase, HMAC). Unregistered, the fallback erases it.
    /// </summary>
    public static DataClassification ItemKey { get; } = new(TaxonomyName, nameof(ItemKey));

    /// <summary>
    /// Free text a peer wrote: an API error's <c>data</c>, a trapper's or agent's <c>info</c>. Zabbix builds it from the
    /// request (<c>Cannot inherit items with key "%1$s"</c>, <c>Macro "%1$s" already exists on "%2$s".</c>), so it can echo
    /// an item key, a macro or a host name that is classified everywhere else. <c>AddZabbixRedaction</c> registers
    /// <see cref="ZabbixPeerTextRedactor"/> for it (the text becomes <c>[redacted]</c>); unregistered, the fallback erases
    /// it. An operator who wants the text on a trusted sink registers a pass-through redactor for it
    /// (<c>services.AddRedaction(r =&gt; r.SetRedactor&lt;NullRedactor&gt;(ZabbixDataClassifications.PeerText))</c>). The structured parts of the same event (the
    /// code, the kind, the error type) are never classified, so the event stays useful erased.
    /// </summary>
    public static DataClassification PeerText { get; } = new(TaxonomyName, nameof(PeerText));
}
